// Called only by local-smoke.mjs against its newly initialized, loopback-only database.
// Accounts/tokens are generated by that harness, never read from the user's database.
import assert from 'node:assert/strict'
import {randomUUID} from 'node:crypto'

export async function checkFeedbackAndReviews({request,sql,owner,other,check}) {
  const token=owner.data.token, otherToken=other.data.token
  const payload={requestId:randomUUID(),name:'隔离测试',contact:'test@example.invalid',subject:'重试测试',message:'本地并发验证，不是真实反馈'}
  const caps=await request('GET','/api/contact-messages/capabilities',undefined,token)
  assert.equal(caps.status,200);assert.equal(caps.data.requestIdVersion,1)
  assert.equal((await request('GET','/api/contact-messages/capabilities')).status,401)
  const responses=await Promise.all(Array.from({length:6},()=>request('POST','/api/contact-messages',payload,token)))
  assert.deepEqual(responses.map(r=>r.status),Array(6).fill(201))
  assert.equal(new Set(responses.map(r=>r.data.id)).size,1)
  assert.equal(await sql('SELECT COUNT(*) FROM contact_messages'),'1')
  assert.equal(await sql('SELECT COUNT(*) FROM contact_submission_keys'),'1')
  const changed=await request('POST','/api/contact-messages',{...payload,message:'修改后不能复用旧编号'},token)
  assert.equal(changed.status,409)
  const otherMessage=await request('POST','/api/contact-messages',payload,otherToken)
  assert.equal(otherMessage.status,201);assert.notEqual(otherMessage.data.id,responses[0].data.id)
  const exportOther=await request('GET','/api/account/export',undefined,otherToken)
  assert.equal(exportOther.status,200)
  assert.equal(await sql('SELECT COUNT(*) FROM contact_messages'),'2')
  assert.equal(await sql('SELECT COUNT(*) FROM contact_submission_keys'),'2')
  check('MySQL repeatable-read: six concurrent feedback retries create one row, conflicts reject and accounts stay separate')

  const projectId=randomUUID(),reviewId=randomUUID()
  const content={title:'HTTP隔离审阅项目',track:'general',deadline:null,brief:'说明实际测量过程',manuscript:'不应分享的材料',requirements:[],dataSheet:null}
  assert.equal((await request('POST','/api/projects',{id:projectId,content},token)).status,200)
  assert.equal((await request('GET',`/api/projects/${projectId}`,undefined,otherToken)).status,404)
  assert.equal((await request('POST',`/api/projects/${projectId}/reviews`,{requestId:reviewId,revision:1,recipient:'smoke_other',includeMaterial:false,includeData:false},token)).status,200)
  const detail=await request('GET',`/api/project-reviews/${reviewId}`,undefined,otherToken)
  assert.equal(detail.status,200);assert.equal(detail.data.noteConcurrencyVersion,1)
  assert.equal(detail.data.content.manuscript,'');assert.equal(detail.data.canReview,true)
  assert.equal((await request('PUT',`/api/project-reviews/${reviewId}`,{note:'冒充对方',baseNote:''},token)).status,404)
  const writes=await Promise.all(['意见A','意见B'].map(note=>request('PUT',`/api/project-reviews/${reviewId}`,{note,baseNote:''},otherToken)))
  assert.deepEqual(writes.map(r=>r.status).sort(),[204,409])
  const current=(await request('GET',`/api/project-reviews/${reviewId}`,undefined,otherToken)).data.entry.reviewNote
  assert.ok(['意见A','意见B'].includes(current))
  assert.equal((await request('PUT',`/api/project-reviews/${reviewId}`,{note:current,baseNote:''},otherToken)).status,204)
  assert.equal((await request('PUT',`/api/project-reviews/${reviewId}`,{note:'无基线'},otherToken)).status,400)
  assert.equal((await request('PUT',`/api/project-reviews/${reviewId}`,{note:'ABC',baseNote:current},otherToken)).status,204)
  assert.equal((await request('PUT',`/api/project-reviews/${reviewId}`,{note:'不应成功',baseNote:'abc'},otherToken)).status,409)
  assert.equal((await request('GET',`/api/projects/${projectId}`,undefined,token)).data.revision,1)
  check('real HTTP review snapshot permissions, concurrent stale edit conflict and exact retry acknowledgement')
  assert.equal((await request('DELETE',`/api/projects/${projectId}/reviews/${reviewId}`,undefined,token)).status,204)
  assert.equal((await request('GET',`/api/project-reviews/${reviewId}`,undefined,otherToken)).status,404)
  assert.equal((await request('PUT',`/api/project-reviews/${reviewId}`,{note:'撤销后不能写',baseNote:'ABC'},otherToken)).status,404)
  assert.equal(await sql(`SELECT snapshot_json FROM project_reviews WHERE id='${reviewId}'`),'{}')
  assert.equal(await sql(`SELECT review_note FROM project_reviews WHERE id='${reviewId}'`),'')
  check('revoked review denies both read/write and removes stored shared material and notes')
}

export async function checkRefreshAndLogout({request,login,check}) {
  const session=await login('smoke_other')
  assert.equal(session.status,200)
  const cookie=session.headers.get('set-cookie')?.split(';')[0]
  assert.ok(cookie?.startsWith('campus_refresh='))
  const rotated=await request('POST','/api/auth/refresh',undefined,undefined,cookie)
  assert.equal(rotated.status,200);assert.equal(rotated.data.user.username,'smoke_other')
  assert.equal((await request('POST','/api/auth/refresh',undefined,undefined,cookie)).status,401)
  const nextCookie=rotated.headers.get('set-cookie')?.split(';')[0]
  assert.ok(nextCookie);assert.notEqual(nextCookie,cookie)
  // Two tabs of the same session may hold access tokens issued before and after refresh.
  assert.equal((await request('GET','/api/auth/me',undefined,session.data.token)).status,200)
  assert.equal((await request('GET','/api/auth/me',undefined,rotated.data.token)).status,200)
  assert.equal((await request('POST','/api/auth/logout',undefined,rotated.data.token,nextCookie)).status,204)
  for(const access of [session.data.token,rotated.data.token]){
    assert.equal((await request('GET','/api/auth/me',undefined,access)).status,401)
    assert.equal((await request('POST','/api/projects',{id:randomUUID(),content:{title:'退出后不应创建',track:'general',brief:'',manuscript:'',requirements:[]}},access)).status,401)
  }
  assert.equal((await request('POST','/api/auth/refresh',undefined,undefined,nextCookie)).status,401)
  check('real refresh-cookie rotation rejects reuse, and logout invalidates both old/new access tokens and private writes')
  const first=await login('smoke_other'),second=await login('smoke_other')
  assert.equal(first.status,200);assert.equal(second.status,200)
  const result=await request('POST','/api/account/sessions/revoke-others',undefined,second.data.token)
  assert.equal(result.status,200);assert.ok(result.data.revoked>=1)
  assert.equal((await request('GET','/api/auth/me',undefined,first.data.token)).status,401)
  assert.equal((await request('GET','/api/auth/me',undefined,second.data.token)).status,200)
  const parallelCookie=second.headers.get('set-cookie')?.split(';')[0]
  const concurrent=await Promise.all([1,2].map(()=>request('POST','/api/auth/refresh',undefined,undefined,parallelCookie)))
  assert.deepEqual(concurrent.map(r=>r.status).sort(),[200,401])
  const winner=concurrent.find(r=>r.status===200)
  assert.equal((await request('POST','/api/auth/logout',undefined,winner.data.token,winner.headers.get('set-cookie').split(';')[0])).status,204)
  check('separate session revocation preserves current login; concurrent refresh has exactly one valid winner')
}
